import {cp,mkdir,readdir,readFile,writeFile,rm} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {resolve,join} from 'node:path';
const infrastructure=resolve(import.meta.dirname,'..'),backend=resolve(infrastructure,'../den-backend'),output=join(infrastructure,'.preview/backend');
// This directory is generated by this script; existing repositories and databases are never touched.
await rm(output,{recursive:true,force:true});await mkdir(output,{recursive:true});
for(const directory of ['src','migrations','vendor'])await cp(join(backend,directory),join(output,directory),{recursive:true});
await cp(join(backend,'package.json'),join(output,'SOURCE_PACKAGE.json'));
const manifest={formatVersion:'1.0.0',source:'DEN-Global/den-backend',files:{}};
async function walk(directory,prefix=''){for(const e of await readdir(directory,{withFileTypes:true})){const path=join(directory,e.name),name=prefix+e.name;if(e.isDirectory())await walk(path,name+'/');else manifest.files[name]=createHash('sha256').update(await readFile(path)).digest('hex');}}
await walk(output);await writeFile(join(output,'PROVENANCE.json'),JSON.stringify(manifest,null,2)+'\n');
// Source + already-built UI artifacts only. No .data, .env, dev.vars, secrets, credentials or node_modules are copied.
console.log(`Snapshotted ${Object.keys(manifest.files).length} backend source and migration files. No remote resource accessed.`);
